mapper.select:
select o.order_id, o.order_date, c.category_name, p.product_name, cnt.cnt - 1 as extra_count from orders o join ( select order_id, min(order_item_id) as rep_order_item_id, count(*) as cnt from order_item group by order_id ) cnt on o.order_id = cnt.order_id join order_item oi on oi.order_item_id = cnt.rep_order_item_id join product p on p.product_id = oi.product_id join category c on c.category_id = p.category_id where o.store_id = #{store_id}
and TRUNC(o.order_date) = TO_DATE(#{order_date}, 'YYYY-MM-DD')
and c.category_id = #{category_id}
and p.product_id = #{product_id}
order by o.order_date desc
